runner = '''    private fun isPoAuthFailure(error: Throwable): Boolean {\n        val message = buildString {\n            var x: Throwable? = error\n            var depth = 0\n            while (x != null && depth++ < 5) { append(x.message ?: "").append('\\n'); x = x.cause }\n        }.lowercase(Locale.US)\n        return message.contains("http error 403") || message.contains("error 403") ||\n            message.contains("forbidden") || message.contains("bot detection") ||\n            message.contains("sign in to confirm") || message.contains("po_token") ||\n            message.contains("po token")\n    }\n\n    private fun executeJob(jobId: String, request: YoutubeDLRequest, dir: File) {\n        YoutubeDL.getInstance().execute(request, jobId) { progress, eta, line ->\n            val state = jobStates[jobId] ?: "running"\n            writeProgress(dir, state, progress.toDouble(), eta, line)\n        }\n    }\n\n    private fun runJob(jobId: String) {\n        val dir = jobs[jobId] ?: return\n        val builder = jobRequestBuilders[jobId] ?: return\n        try {\n            if (jobStates[jobId] != "running") return\n            ensureEngine()\n            if (jobStates[jobId] != "running") return\n            writeProgress(dir, "starting", 0.0, null, "Starting download…")\n            try {\n                executeJob(jobId, builder(), dir)\n            } catch (firstError: Exception) {\n                if (!jobYoutube.getOrDefault(jobId, false) || !isPoAuthFailure(firstError)) throw firstError\n                var success = false\n                var lastError: Exception = firstError\n                for (attempt in 1..3) {\n                    if (jobStates[jobId] == "paused" || jobStates[jobId] == "cancelled") return\n                    log("PO-token retry $attempt/3: invalidating token and creating a fresh WebView authentication session for job=$jobId")\n                    writeProgress(dir, "retrying", readPercent(dir).toDouble(), null, "Refreshing YouTube authentication… attempt $attempt/3")\n                    try {\n                        poTokenProvider.invalidateToken()\n                        poTokenProvider.refreshToken(25)\n                        executeJob(jobId, builder(), dir)\n                        success = true\n                        log("PO-token retry $attempt/3 succeeded for job=$jobId")\n                        break\n                    } catch (retryError: Exception) {\n                        lastError = retryError\n                        log("PO-token retry $attempt/3 failed for job=$jobId", retryError)\n                    }\n                }\n                if (!success) {\n                    val cookieBuilder = jobCookieRequestBuilders[jobId] ?: throw lastError\n                    log("All 3 PO-token retries failed; switching to cookie-only fallback for job=$jobId", lastError)\n                    writeProgress(dir, "retrying", readPercent(dir).toDouble(), null, "Retrying with imported YouTube cookies…")\n                    executeJob(jobId, cookieBuilder(), dir)\n                }\n            }\n            when (jobStates[jobId]) {\n                "paused" -> { writeStatus(dir, "{\\"status\\":\\"paused\\",\\"percent\\":${readPercent(dir)}}"); return }\n                "cancelled" -> { writeStatus(dir, "{\\"status\\":\\"cancelled\\",\\"percent\\":0}"); cleanupJob(jobId, true); return }\n            }\n            val source = dir.walkTopDown().filter { it.isFile && !it.name.endsWith(".part") && it.name != "android_status.json" }.maxByOrNull { it.lastModified() }\n                ?: throw IllegalStateException("yt-dlp completed but no output file was found")\n            val saved = saveToDownloads(source, source.name, jobDestinationUris[jobId])\n            writeStatus(dir, JSONObject().apply { put("status", "completed"); put("percent", 100); put("filename", saved.first); put("uri", saved.second); put("size", source.length()); put("speed", JSONObject.NULL) }.toString())\n            log("Download $jobId completed: ${saved.first} destination=${saved.second}")\n            source.delete()\n        } catch (e: Exception) {\n            val state = jobStates[jobId]\n            if (state == "paused") { writeStatus(dir, "{\\"status\\":\\"paused\\",\\"percent\\":${readPercent(dir)}}"); return }\n            if (state == "cancelled") { writeStatus(dir, "{\\"status\\":\\"cancelled\\",\\"percent\\":0}"); cleanupJob(jobId, true); return }\n            val msg = diagnostic(e)\n            log("Download $jobId FAILED: $msg", e)\n            exportLogToDownloads()\n            writeStatus(dir, JSONObject().apply { put("status", "failed: $msg"); put("percent", 0); put("error", msg); put("exception", e::class.java.name) }.toString())\n        }\n    }\n\n'''
