save = '''    private fun saveToDownloads(source: File, name: String, destinationUri: Uri?): Pair<String, String> {\n        val safe = name.replace(Regex("[\\\\/:*?\\\"<>|]"), "_")\n        val mime = when (safe.substringAfterLast('.', "").lowercase(Locale.US)) {\n            "mp4" -> "video/mp4"; "mkv" -> "video/x-matroska"; "webm" -> "video/webm";\n            "m4a" -> "audio/mp4"; "opus" -> "audio/ogg"; "mp3" -> "audio/mpeg";\n            "flac" -> "audio/flac"; else -> "application/octet-stream"\n        }\n        if (destinationUri != null) {\n            val tree = DocumentFile.fromTreeUri(context, destinationUri) ?: throw IllegalStateException("Selected download folder is no longer accessible")\n            if (!tree.canWrite()) throw IllegalStateException("Selected download folder is not writable")\n            var targetName = safe\n            var counter = 1\n            while (tree.findFile(targetName) != null) {\n                val dot = safe.lastIndexOf('.')\n                targetName = if (dot > 0) safe.substring(0, dot) + " (" + counter++ + ")" + safe.substring(dot) else "$safe (${counter++})"\n            }\n            val target = tree.createFile(mime, targetName) ?: throw IllegalStateException("Could not create output in selected folder")\n            try {\n                context.contentResolver.openOutputStream(target.uri)?.use { out -> source.inputStream().use { it.copyTo(out) } } ?: throw IllegalStateException("Could not open selected-folder output")\n                return targetName to target.uri.toString()\n            } catch (e: Exception) { target.delete(); throw e }\n        }\n        val resolver = context.contentResolver\n        val values = ContentValues().apply { put(MediaStore.Downloads.DISPLAY_NAME, safe); put(MediaStore.Downloads.MIME_TYPE, mime); put(MediaStore.Downloads.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS); put(MediaStore.Downloads.IS_PENDING, 1) }\n        val uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values) ?: throw IllegalStateException("Could not create Downloads entry")\n        try {\n            resolver.openOutputStream(uri)?.use { out -> source.inputStream().use { it.copyTo(out) } } ?: throw IllegalStateException("Could not open Downloads output")\n            values.clear(); values.put(MediaStore.Downloads.IS_PENDING, 0); resolver.update(uri, values, null, null)\n            return safe to uri.toString()\n        } catch (e: Exception) { resolver.delete(uri, null, null); throw e }\n    }\n'''
